uniform float u_cmin;
uniform float u_cmax;
float cmap(float val) { return (val - u_cmin) / (u_cmax - u_cmin); }


uniform sampler2D texture2D_LUT;
vec4 colormap(float t) {
    // Map NaN to bad_color
    if (!(t <= 0.0 || 0.0 <= t)) {
        return vec4(0.000, 0.000, 0.000, 0.000);
    }
    return texture2D(texture2D_LUT, vec2(0.0, clamp(t, 0.0, 1.0)));
}


vec4 chain(float val) {
    float result_1 = cmap(val);
    vec4 result_2 = colormap(result_1);
    return result_2;
}

